# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: emit
def emit(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: sift
def sift(xs, factor=10):
    return [v * factor for v in xs]

# region: render
def render(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: fold
def fold(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return fold(render(sift(emit(gather(raw)))))

